@dataclass(frozen=True, slots=True)
class WitnessSet:
    """Describe information targets that must all be supported together."""

    members: tuple[Hashable, ...]

    def __post_init__(self) -> None:
        """Require distinct, hashable native or caller-owned target identities."""
        if not self.members:
            msg = "A witness set must contain at least one target."
            raise ValueError(msg)
        try:
            unique = set(self.members)
        except TypeError as error:
            msg = "Witness targets must be hashable identities."
            raise ValueError(msg) from error
        if len(unique) != len(self.members):
            msg = "A witness set must not repeat target identities."
            raise ValueError(msg)

def _satisfied_alternative(
    obligation: LocalizationObligation,
    assessment: LocalizationAssessment,
) -> int | None:
    """Return the first completely supported caller-declared witness alternative."""
    supports = {item.target for item in assessment.supported_witnesses}
    return next(
        (
            index
            for index, alternative in enumerate(obligation.witness_alternatives)
            if set(alternative.members) <= supports
        ),
        None,
    )

def promote_supported_hypothesis(
    view: WitnessResolutionView, identity: CandidateHypothesisIdentity
) -> PromotedWitnessHypothesis:
    """Explicitly create accepted values; mutate no assessment or readiness."""
    resolution = view.for_hypothesis(identity)
    if resolution is None:
        msg = "Witness promotion requires a recorded hypothesis resolution."
        raise ValueError(msg)
    return PromotedWitnessHypothesis(resolution)

def for_obligation(
    self, obligation: LocalizationObligationIdentity
) -> tuple[CandidateHypothesisResolution, ...]:
    """Keep competing recorded hypotheses independently queryable."""
    self.candidates.for_obligation(obligation)
    return tuple(
        item
        for item in self.hypotheses
        if item.hypothesis.identity.obligation == obligation
    )

@dataclass(frozen=True, slots=True)
class DeferredDiscovery:
    """Name a later observation and caller acceptance of conditional handoff."""

    observation: str
    reason: str
    accepted_for_handoff: bool = False

    def __post_init__(self) -> None:
        """Require a named observation and why it cannot yet be performed."""
        if not self.observation.strip() or not self.reason.strip():
            msg = "Deferred discovery needs an observation and reason."
            raise ValueError(msg)

if self.disposition is Disposition.DEFERRED_DISCOVERY and self.deferred is None:
    msg = "Deferred disposition must name its later observation."
    raise ValueError(msg)
if (
    self.disposition is not Disposition.DEFERRED_DISCOVERY
    and self.deferred is not None
):
    msg = "Only a deferred disposition may carry a deferred observation."
    raise ValueError(msg)

def _assessment_matches_frame(
    assessment: LocalizationAssessment,
    obligation: LocalizationObligation,
    *,
    repository_id: RepositoryId,
    snapshot_id: RepositorySnapshotId,
) -> bool:
    """Check status semantics, applicability evidence, and witness provenance."""
    if (
        assessment.repository_id != repository_id
        or assessment.snapshot_id != snapshot_id
    ):
        return False
    if obligation.applicability_condition is None:
        if assessment.applicability is not ApplicabilityStatus.NOT_REQUIRED:
            return False
    elif assessment.applicability is ApplicabilityStatus.NOT_REQUIRED:
        return False
    needs_condition_evidence = assessment.applicability in {
        ApplicabilityStatus.APPLIES,
        ApplicabilityStatus.DOES_NOT_APPLY,
    }
    if needs_condition_evidence and not assessment.applicability_evidence:
        return False
    return all(
        item.repository_id == repository_id and item.snapshot_id == snapshot_id
        for item in _evidence_references(assessment)
    )

def _consistent_disposition(
    obligation: LocalizationObligation,
    assessment: LocalizationAssessment,
    *,
    satisfied_alternative: int | None,
) -> bool:
    """Reject claims that contradict the obligation's condition or witness sets."""
    conditional = obligation.applicability_condition is not None
    if assessment.disposition is Disposition.NOT_APPLICABLE:
        return (
            conditional
            and assessment.applicability is ApplicabilityStatus.DOES_NOT_APPLY
            and bool(assessment.applicability_evidence)
            and not assessment.supported_witnesses
        )
    if assessment.applicability is ApplicabilityStatus.DOES_NOT_APPLY:
        return False
    if assessment.disposition is Disposition.RESOLVED:
        return (
            not conditional or assessment.applicability is ApplicabilityStatus.APPLIES
        ) and satisfied_alternative is not None
    return satisfied_alternative is None

def _record_mandatory(
    obligation: LocalizationObligation,
    assessment: LocalizationAssessment | None,
    *,
    invalid: bool,
    diagnostics: _Diagnostics,
) -> None:
    """Classify mandatory coverage without treating deferral as resolution."""
    if assessment is None or invalid:
        diagnostics.unresolved.append(obligation.identity)
    elif assessment.disposition is Disposition.RESOLVED:
        diagnostics.resolved.append(obligation.identity)
    elif assessment.disposition is Disposition.NOT_APPLICABLE:
        diagnostics.not_applicable.append(obligation.identity)
    elif assessment.disposition is Disposition.ABSTAINED:
        diagnostics.abstained.append(obligation.identity)
        diagnostics.unresolved.append(obligation.identity)
    elif assessment.disposition is Disposition.DEFERRED_DISCOVERY:
        diagnostics.deferred.append(obligation.identity)
        if assessment.deferred is None or not assessment.deferred.accepted_for_handoff:
            diagnostics.unresolved.append(obligation.identity)
    else:
        diagnostics.unresolved.append(obligation.identity)


def _readiness_state(
    *,
    frame_valid: bool,
    frame_errors: tuple[str, ...],
    diagnostics: _Diagnostics,
) -> HandoffReadiness:
    """Prioritize invalid input, open obligations, deferral, then readiness."""
    if not frame_valid:
        return HandoffReadiness.INVALID_FRAME
    if frame_errors or diagnostics.unresolved:
        return HandoffReadiness.BLOCKED
    if diagnostics.deferred:
        return HandoffReadiness.CONDITIONAL
    return HandoffReadiness.READY

@dataclass(frozen=True, slots=True)
class CandidateHypothesisResolution:
    """Retain recorded conjunct decisions and derive their hypothesis state."""

    candidates: CandidateWitnessView
    hypothesis: CandidateWitnessHypothesis
    members: tuple[CandidateMemberResolution, ...]

    def __post_init__(self) -> None:
        """Require at least one decision and reject mixed or repeated members."""
        if not self.members or any(
            item.candidates is not self.candidates
            or item.hypothesis is not self.hypothesis
            for item in self.members
        ):
            msg = "Hypothesis resolution needs decisions from its exact frame."
            raise ValueError(msg)
        if len({item.member.target for item in self.members}) != len(self.members):
            msg = "Hypothesis resolution repeats a member decision."
            raise ValueError(msg)
        object.__setattr__(
            self,
            "members",
            tuple(
                sorted(
                    self.members,
                    key=lambda item: item.member.target.address.value,
                )
            ),
        )

    @property
    def disposition(self) -> HypothesisResolutionDisposition:
        """Contradiction dominates; complete support needs every conjunct."""
        if any(
            item.disposition is MemberResolutionDisposition.CONTRADICTED
            for item in self.members
        ):
            return HypothesisResolutionDisposition.CONTRADICTED
        if len(self.members) == len(self.hypothesis.members) and all(
            item.disposition is MemberResolutionDisposition.SUPPORTED
            for item in self.members
        ):
            return HypothesisResolutionDisposition.COMPLETELY_SUPPORTED
        return HypothesisResolutionDisposition.UNRESOLVED

    @property
    def unrecorded_members(self) -> tuple[CandidateWitnessMember, ...]:
        """Distinguish missing decisions from explicitly unresolved decisions."""
        recorded = {item.member.target for item in self.members}
        return tuple(
            item for item in self.hypothesis.members if item.target not in recorded
        )

@dataclass(frozen=True, slots=True)
class PromotedWitnessHypothesis:
    """Supply accepted values while retaining every explicit resolution decision."""

    resolution: CandidateHypothesisResolution

    def __post_init__(self) -> None:
        """Permit only complete explicit all-member support."""
        WitnessResolutionView(self.resolution.candidates, self.resolution.members)
        if (
            self.resolution.disposition
            is not HypothesisResolutionDisposition.COMPLETELY_SUPPORTED
        ):
            msg = "Witness promotion requires a completely supported hypothesis."
            raise ValueError(msg)

    @property
    def witness_set(self) -> WitnessSet:
        """Reuse native targets and existing complementary witness algebra."""
        return WitnessSet(tuple(item.member.target for item in self.resolution.members))

    @property
    def supported_witnesses(self) -> tuple[SupportedWitness, ...]:
        """Retain native evidence references and the immutable caller decision."""
        return tuple(
            SupportedWitness(
                item.member.target,
                (
                    *item.basis,
                    LocalizationEvidenceReference(
                        item, item.repository_id, item.snapshot_id
                    ),
                ),
            )
            for item in self.resolution.members
        )


def promote_supported_hypothesis(
    view: WitnessResolutionView, identity: CandidateHypothesisIdentity
