    )


def _evidence_references(
    assessment: LocalizationAssessment,
) -> tuple[LocalizationEvidenceReference, ...]:
    """Collect exact provenance from applicability and witness supports."""
    return (
        *assessment.applicability_evidence,
        *(
            reference
            for witness in assessment.supported_witnesses
            for reference in witness.evidence
        ),
    )

    def __post_init__(self) -> None:
        """Validate exact membership, criterion and caller-owned evidence lineage."""
        if not isinstance(self.disposition, MemberResolutionDisposition):
            msg = "Member resolution needs an explicit disposition."
            raise TypeError(msg)
        if not all(text.strip() for text in (self.claim, self.reason, self.caller)):
            msg = "Member resolution needs a claim, reason and named caller."
            raise ValueError(msg)
        if not any(item is self.hypothesis for item in self.candidates.hypotheses):
            msg = "Resolution hypothesis is foreign or stale to its candidate view."
            raise ValueError(msg)
        if not any(item is self.member for item in self.hypothesis.members):
            msg = "Resolution member is foreign to its exact candidate hypothesis."
            raise ValueError(msg)
        obligation = next(
            (
                item
                for item in self.candidates.task.obligations
                if item.identity == self.hypothesis.identity.obligation
            ),
            None,
        )
        if obligation is None or self.criterion != obligation.satisfaction:
            msg = "Resolution criterion differs from the obligation criterion."
            raise ValueError(msg)
        if (
            self.disposition
            in {
                MemberResolutionDisposition.SUPPORTED,
                MemberResolutionDisposition.CONTRADICTED,
            }
            and not self.basis
        ):
            msg = "Support or contradiction requires an explicit evidence basis."
            raise ValueError(msg)
        self._validate_basis()

    def _validate_basis(self) -> None:
        """Canonicalize only exact attached native supports in this frame."""
        supports = (
            *self.member.lexical,
            *self.member.roles,
            *self.member.routed,
            *self.member.structural,
        )
        positions = []
        for reference in self.basis:
            if (
                reference.repository_id != self.repository_id
                or reference.snapshot_id != self.snapshot_id
            ):
                msg = "Resolution evidence is foreign to the repository/snapshot."
                raise ValueError(msg)
            position = next(
                (
                    index
                    for index, support in enumerate(supports)
                    if support is reference.identity
                ),
                None,
            )
            if position is None:
                msg = "Resolution evidence is not an exact attached member support."
                raise ValueError(msg)
            positions.append(position)
        if len(set(positions)) != len(positions):
            msg = "Resolution basis repeats native support."
            raise ValueError(msg)
        object.__setattr__(
            self,
            "basis",
            tuple(
                reference
                for _, reference in sorted(zip(positions, self.basis, strict=True))
            ),
        )

    @property
    def task(self) -> LocalizationTaskIdentity:
        """Retain the exact task identity without a parallel resolution task."""
        return self.candidates.task.identity

    @property
    def obligation(self) -> LocalizationObligationIdentity:
        """Bind the decision to the candidate's named obligation."""
        return self.hypothesis.identity.obligation

    @property
    def repository_id(self) -> RepositoryId:
        """Use the retained candidate repository frame."""
        return self.candidates.snapshot.repository_id

    @property
    def snapshot_id(self) -> RepositorySnapshotId:
        """Use the retained candidate snapshot frame."""
        return self.candidates.snapshot.id

@dataclass(frozen=True, slots=True)
class LocalizationTaskInterpretation:
    """Group explicit task anchors and obligations before selecting a snapshot."""

    identity: LocalizationTaskIdentity
    provenance: TaskProvenance
    anchors: tuple[LocalizationAnchor, ...]
    obligations: tuple[LocalizationObligation, ...]

    def __post_init__(self) -> None:
        """Validate deterministic task-local uniqueness and all anchor references."""
        anchor_ids = tuple(item.identity for item in self.anchors)
        obligation_ids = tuple(item.identity for item in self.obligations)
        if any(item.task != self.identity for item in anchor_ids) or any(
            item.task != self.identity for item in obligation_ids
        ):
            msg = "Task interpretation contains a foreign task-local identity."
            raise ValueError(msg)
        if len(set(anchor_ids)) != len(anchor_ids):
            msg = "Task interpretation contains duplicate anchor identities."
            raise ValueError(msg)
        if len(set(obligation_ids)) != len(obligation_ids):
            msg = "Task interpretation contains duplicate obligation identities."
            raise ValueError(msg)
        known_anchors = set(anchor_ids)
        if any(
            anchor not in known_anchors
            for obligation in self.obligations
            for anchor in obligation.anchors
        ):
            msg = "Obligation references an anchor outside its task interpretation."
            raise ValueError(msg)

@dataclass(frozen=True, slots=True)
class RepositorySnapshot:
    """Represent complete state for an explicit required resource collection."""

    OBSERVATION_SEMANTICS: ClassVar[str] = "explicit-required-text-resources-sha256-v1"

    id: RepositorySnapshotId
    repository_id: RepositoryId
    resources: tuple[RepositoryResourceOccurrence, ...]

    @property
    def resource(self) -> RepositoryResourceOccurrence:
        """Return the sole occurrence for compatible single-resource consumers."""
        if len(self.resources) != 1:
            msg = "Repository snapshot does not contain exactly one resource."
            raise ValueError(msg)
        return self.resources[0]

    def resource_at(
        self,
        address: RepositoryResourceAddress,
    ) -> RepositoryResourceOccurrence:
        """Return the observed occurrence at one exact requested address."""
        for resource in self.resources:
            if resource.address == address:
                return resource
        msg = f"Repository snapshot does not contain resource address: {address}."
        raise ValueError(msg)

def _record_mandatory(
    obligation: LocalizationObligation,
    assessment: LocalizationAssessment | None,
    *,
    invalid: bool,
    diagnostics: _Diagnostics,
) -> None:
    """Classify mandatory coverage without treating deferral as resolution."""
    if assessment is None or invalid:
        diagnostics.unresolved.append(obligation.identity)
    elif assessment.disposition is Disposition.RESOLVED:
        diagnostics.resolved.append(obligation.identity)
    elif assessment.disposition is Disposition.NOT_APPLICABLE:
        diagnostics.not_applicable.append(obligation.identity)
    elif assessment.disposition is Disposition.ABSTAINED:
        diagnostics.abstained.append(obligation.identity)
        diagnostics.unresolved.append(obligation.identity)
    elif assessment.disposition is Disposition.DEFERRED_DISCOVERY:
        diagnostics.deferred.append(obligation.identity)
        if assessment.deferred is None or not assessment.deferred.accepted_for_handoff:
            diagnostics.unresolved.append(obligation.identity)
    else:
        diagnostics.unresolved.append(obligation.identity)


