def supported_obligations(self) -> tuple[LocalizationObligationIdentity, ...]:
    """Report supported candidate presence, not satisfied obligation coverage."""
    supported = {
        item.hypothesis.identity.obligation for item in self.completely_supported
    }
    return tuple(
        item.identity
        for item in self.candidates.task.obligations
        if item.identity in supported
    )

def pytest_arguments(repository_root: Path = REPOSITORY_ROOT) -> list[str]:
    """Select ordinary tests while excluding the retained experiment tree."""
    tests = repository_root / "tests"
    experiments = tests / "experiments"
    return [str(tests), f"--ignore={experiments}"]


def main() -> int:
    """Run pytest and return its exit code unchanged."""
    return int(pytest.main(pytest_arguments()))


if __name__ == "__main__":
